import { MenuItem } from '@/store/menu';
import { Pattern } from '@/types/pattern';
import { Form, FormInstance } from '@arco-design/web-react';
import { observable, action, computed, toJS, makeObservable } from 'mobx';
import React from 'react';

class Store {
    values: Partial<MenuItem> = {}
    form: FormInstance;

    @observable visible = false;
    @action
    setVisible = (bool, params: Partial<MenuItem> = {}) => {
        this.visible = bool;
        this.values = params;
    }

    @observable copyVisible = false;
    @action
    setCopyVisible = (bool, params: Partial<MenuItem> = {}) => {
        this.visible = bool;
        this.values = params;
    }

    @observable select = "";
    @action onSelect = (list) => {
        this.select = list[0];
    }

    @observable expandedKeys: string[] = [];
    @action
    setExpandedKeys = (list) => {
        this.expandedKeys = list;
    }

    constructor() {
        makeObservable(this);
    }

    @computed get expandedList(){
        return toJS(this.expandedKeys);
    }

    addExpandedKeys = (item) => {
        this.setExpandedKeys([...this.expandedList, item.id])
    }

    saveExpandedKeys = (item) => {
        if(this.expandedList.find((o) => o == item.id)){
            this.setExpandedKeys(this.expandedList.filter((o) => o != item.id));                                
        }else {
            this.addExpandedKeys(item)
        }
    }

    schema: JSONSchema = {
        "type": "object",
        "title": "菜单",
        "properties": {
            "parentId": {
                "type": "string",
                "title": "上级菜单",
                "colProps": {
                    "span": 24
                },
                "format": "treeSelector",
                "fieldProps": {
                    "type": "menu"	
                },
                "default": null,
            },
            "type": {
                "type": "string",
                "title": "菜单类型",
                "colProps": {
                    "span": 24,
                },
                "format": "radio",
                "enum": [
                    { "label": "目录", "value": "directory" },
                    { "label": "菜单", "value": "menu" },
                    // { "label": "外链", "value": "href" },
                ],
                "default": "directory"
            },
            "name": {
                "type": "string",
                "title": "菜单名称",
                "maxLength": 50,
                "default": null
            },
            "path": {
                "type": "string",
                "title": "路由地址",
                // "pattern": '^[0-9a-z]+$',
                "maxLength": 100,
                "default": null
            },
            "isShow": {
                "type": "boolean",
                "title": "是否显示",
                "format": "radio",
                "enum": [
                    { "value": 1, "label": "显示", "color": "blue" },
                    { "value": 0, "label": "隐藏", "color": "red" }
                ],
                "formItemProps": {
                    "tooltip": "关闭则路由将不会出现在侧边栏，但仍然可以访问",
                },
                "default": 1
            },
            "isActive": {
                "type": "boolean",
                "title": "菜单状态",
                "format": "radio",
                "enum": [
                    { "value": 1, "label": "正常", "color": "blue" },
                    { "value": 0, "label": "关闭", "color": "red" },
                ],
                "formItemProps": {
                    "tooltip": "关闭则路由将不会出现在侧边栏，也不能被访问",
                },
                "default": 1
            },
        },
        "required": ['name', 'path']
    }

    copySchema: JSONSchema = {

    }

    @observable search: string = '';
    @action
    setSearch = (str) => {
        this.search = str;
    }
}

export default new Store();