import { Button, Card, Link, ResizeBox, Space, Collapse, Input, Form, Result, Modal, Menu, Dropdown, Empty } from '@arco-design/web-react';
import react, { useEffect, useMemo, useState } from 'react';
import styles from './index.module.less';
import store from './store';
import { SchemaForm } from '@/components/schema';
import ajax from '@/utils/ajax';
import classNames from 'classnames';
import menuStore, { MenuItem } from '@/store/menu';
import { observer } from 'mobx-react-lite';
import { DorpTree } from '@/components/custom';
import { convertToTree, filterTreeData, getSpecificValues, getUuid, searchTreeNode } from '@/utils';
import { toJS } from 'mobx';
import Body from './components/Body';
import { IconCopy, IconDelete, IconFile, IconFolder, IconMoreVertical, IconPlus } from '@arco-design/web-react/icon';
import app from '@/store/app';
import BodyList from './components/BodyList';
import i18next from 'i18next';
const { Search } = Input;

const Index = () => {

    const [form] = Form.useForm();
    store.form = form;
    const menuList = useMemo(() => {
        const list = convertToTree(toJS(menuStore.menus));
        return getSpecificValues(
            list,
            (item, parentItem) => {
                const { paths } = parentItem || {};
                return {
                    ...item,
                    icon: undefined,
                    paths: `${paths? `${paths}/` : '/'}${item.path}`
                }
            }
        )
    },[menuStore.menus])

    const list = useMemo(() => {
        if(!store.search) return menuList;
        return filterTreeData(menuList, (item) => {
            const bool = item.name?.indexOf(store.search) !== -1 || (item.paths && item.paths.indexOf(store.search) !== -1);
            return bool;
        })
    },[store.search, menuList])
    
    const node = useMemo(() => {
        return searchTreeNode(menuList, store.select);
    },[menuList, store.select])


    useEffect(() => {
        menuStore.getMenuList();
    },[])


    return (
        <div className={classNames(styles.pages, 'page-container')}>
            <ResizeBox
                className={styles.resize}
                directions={['right']}
            >
                <div className={styles.listHeader}>
                    <Search
                        className={styles.serach}
                        value={store.search}
                        onChange={store.setSearch}
                        allowClear
                        placeholder='搜索路由'
                        style={{ width: "100%" }}
                    />
                    <Button type="primary"
                        onClick={() => {
                            store.setVisible(true)
                            form.clearFields();
                        }}
                    >新增</Button>
                </div>
                <div className={styles.listBody}>
                    <DorpTree
                        value={list}
                        selectedKeys={[store.select]}
                        onSelect={(keys, extra) => {
                            // const item: MenuItem = extra.node.props.dataRef as any;
                            // setList(item.children);
                            store.onSelect(keys);
                        }}
                        draggable={false}
                        fieldNames={{
                            key: "id",
                            title: "name"
                        }}
                        expandedKeys={store.expandedList}
                        onExpand={store.setExpandedKeys}
                        className={styles.treeItem}
                        renderTitle={(node: any) => {
                            const item: MenuItem = node.dataRef;
                            const menuList = (
                                <Menu
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        e.preventDefault();
                                    }}
                                >
                                    <Menu.Item key="categor" disabled={Boolean(node.parentId)}
                                        onClick={() => {
                                            store.setVisible(true, {
                                                parentId: node.id,
                                                type: "directory"
                                            })
                                            form.clearFields();
                                        }}
                                    >
                                        <IconPlus /> 新增路由
                                    </Menu.Item>
                                    <Menu.Item key="api" disabled={item.type === "menu"}
                                        onClick={() => {
                                            form.clearFields();
                                            store.setVisible(true, {
                                                parentId: node.id,
                                                type: "menu",
                                            })
                                            setTimeout(() => {
                                                form.setFieldsValue(store.values)  
                                            })
                                        }}
                                    >
                                        <IconPlus /> 新增页面
                                    </Menu.Item>
                                    <Menu.Item key='copy' disabled={item.type !== "menu"}
                                        onClick={() => menuStore.copyNode(node)}
                                    >
                                        <IconCopy /> 复制
                                    </Menu.Item>
                                    <Menu.Item key='del'
                                        onClick={() => menuStore.deleteNode(item)}
                                    >
                                        <IconDelete /> 删除
                                    </Menu.Item>
                                </Menu>
                            )

                            return (
                                <div className={styles.treeItemTitle} 
                                    // onClick={() => store.saveExpandedKeys(node)}
                                    onDoubleClick={() => store.saveExpandedKeys(node)}
                                >
                                    <span>
                                        {item.type === "directory" && <IconFolder />}
                                        {item.type === "menu" && <IconFile />}
                                        <span className={styles.titleText}>{i18next.t(node.title)}</span>
                                    </span>
                                    <Dropdown  droplist={menuList} position='bl' trigger="click">
                                        <Button size="small" icon={<IconMoreVertical />} 
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                e.preventDefault();
                                            }}
                                        />
                                    </Dropdown>
                                </div>
                            )
                        }}
                    />
                </div>
            </ResizeBox>
            <div className={styles.body}>
                <div className={styles.bodyList}>
                    {node? (
                        <Body node={node} />
                    ):(
                        list.length? <BodyList list={list} /> :<Empty description="暂无数据" />
                    )}
                </div>
            </div>

            <Modal
                visible={store.visible}
                title={`${store.values.id? '编辑' : "新增"}路由`}
                style={{ width: 600 }}
                onCancel={() => {
                    store.setVisible(false)
                }}
                onOk={() => {
                    return form.validate().then((res) => {
                        return menuStore.saveMenu({
                            ...store.values,
                            ...res
                        }).then(() => {
                            store.setVisible(false)
                        });
                    })
                }}
                unmountOnExit
            >
                <SchemaForm
                    schema={store.schema}
                    initialValues={store.values}
                    form={form}
                    generagteProps={{ cols: 24,  }}
                />
            </Modal>
            {/* <Modal
                visible={store.copyVisible}
                title={`复制路由【${store.values.name}】`}
            >
                <SchemaForm
                    schema={store.copySchema}
                    form={form}
                    generagteProps={{ cols: 24 }}
                />
            </Modal> */}
        </div>
    )
}

export default observer(Index);