import React, { useMemo } from 'react';
import { MenuItem } from '@/store/menu';
import { Card, Collapse, Grid } from '@arco-design/web-react';
import { dynamicCreateModule } from '@/environments/hoc';
import BodyList from './BodyList';
import PageContent from './PageContent';

const CollapseItem = Collapse.Item;

interface BodyProps {
    node: MenuItem
}

const BodyPage = () => {

    return <span>111</span>
}

const Body = ({ node }: BodyProps) => {

    if(node.type === "menu"){
        return (
            <PageContent item={node} notScale />
        )
    }
    return (
        <div>
            {Boolean(node.children) && (
                <BodyList list={node.children} />
            )}
        </div>
    )
}

export default Body;