import React, { useMemo } from 'react';
import { Avatar, Button, Card, CardProps, Divider, Dropdown, Empty, Menu, Message, Space, Switch, Tooltip, Typography } from '@arco-design/web-react';
import { IconCodeSquare, IconEdit, IconEye, IconFile, IconMore, IconShareInternal, IconThumbUp } from '@arco-design/web-react/icon';
import store from '../store';
import menuStore from '@/store/menu';
import _ from 'lodash';
import { MenuItem } from '@/store/menu';
import styles from '../index.module.less';
import classNames from 'classnames';
import { useHistory } from 'react-router-dom';
import { useObserver } from 'mobx-react-lite';
import { AsyncButton, MyErrorBoundary } from '@/components/custom';
import plugin from '@/store/plugin';
import i18next from 'i18next';

interface PageContent extends CardProps {
    item: MenuItem;
    // 是否禁止缩放
    notScale?: boolean;
}
const PageContent = ({ item, notScale, ...props }: PageContent) => {
    const history = useHistory();
    const page = menuStore.pages[item.pageId];

    return useObserver(() => {

        const Element: any = useMemo(() => {
            if(page.render) return page.render;
            return () => <Empty />
        },[page.render])

        const menuList = (
            <Menu
                onClick={(e) => {
                    e.stopPropagation();
                    e.preventDefault();
                }}
            >
                <Menu.Item key="menu"
                    onClick={() => {
                        store.setVisible(true, item);
                        store.form.clearFields();
                        setTimeout(() => {
                            store.form.setFieldsValue(_.pick(item,['name', 'type', 'parentId', 'path']))
                        })
                    }}
                >
                    编辑菜单
                </Menu.Item>
                <Menu.Item key="categor"
                    onClick={() => {
                        window.open(`#/plugin-view/${plugin.info.id}/admin/${item.path}`)
                    }}
                >
                    访问页面
                </Menu.Item>
                <Menu.Item key="api"
                    onClick={() => {
                        
                    }}
                >
                    页面日志
                </Menu.Item>
                <Menu.Item key='copy'
                    onClick={() => {

                    }}
                >
                    菜单日志
                </Menu.Item>
            </Menu>
        )

    
        return (
            <Card {...props} size="small"
                title={(
                    <span>
                        {i18next.t(item?.name)}
                        <Divider type="vertical" />
                        <Typography.Text>
                            {item.path}
                        </Typography.Text>
                    </span>
                )}
                extra={(
                    <Space>
                        <Tooltip content="设置页面状态">
                            <Switch checked={page.isActive} size="small" 
                                onClick={() => {
                                    page.updateIsActive()
                                }}
                            />
                        </Tooltip>
                        <Tooltip content="页面开发">
                            <AsyncButton type="primary" size="small" icon={<IconCodeSquare />}
                                onClick={async () => {
                                    history.push(`/pages/save?pageId=${item.pageId}`);
                                }}
                            />
                        </Tooltip>
                        <Dropdown  droplist={menuList} position='bl' trigger="click">
                            <Button size="small" icon={<IconMore />} />
                        </Dropdown>
                    </Space>
                )}
                actions={[
                    <span className='icon-hover'>
                      <IconThumbUp />
                    </span>,
                    <span className='icon-hover'>
                      <IconShareInternal />
                    </span>,
                    <span className='icon-hover'>
                      <IconMore />
                    </span>,
                ]}
            >
                <div className={styles.container}>
                    <div className={classNames({
                        [styles.content]: true,
                        [styles.contentScale]: !notScale,
                    })}
                        onDoubleClick={async () => {
                            if(!page) await menuStore.createPage(item)
                            history.push(`/pages/save?pageId=${item.pageId}`);
                        }}
                    >
                        <MyErrorBoundary>
                            <Element />
                        </MyErrorBoundary>
                    </div>
                </div>
                <Card.Meta
                    avatar={
                        <Space>
                            {/* <Avatar size={24}>{page?.userId}</Avatar> */}
                            <Typography.Text>
                                {page?.userId}
                                <Divider type="vertical" />
                                更新时间：{page? page.updateTime: "暂无"}
                            </Typography.Text>
                        </Space>
                    }
                />
            </Card>
        )
    })
}

export default PageContent;